package com.cloudinfra.sdk.iam

import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap

/**
 * Cloud Infrastructure SDK - Resource Quota Manager
 * Handles per-tenant resource allocation with RBAC enforcement
 */

enum class Role(val level: Int) {
    VIEWER(1),
    DEVELOPER(2),
    ADMIN(3),
    SUPER_ADMIN(4)
}

data class Principal(val tenantId: String, val userId: String, val role: Role)

data class QuotaAllocation(
    val cpuMillicores: Int,
    val memoryMiB: Int,
    val storageGiB: Int,
    val networkBandwidthMbps: Int
)

class ResourceQuotaManager {
    private val tenantQuotas = ConcurrentHashMap<String, QuotaAllocation>()
    private val tenantUsage = ConcurrentHashMap<String, QuotaAllocation>()
    private val auditLog = mutableListOf<String>()

    companion object {
        const val MAX_CPU_PER_TENANT = 128000        // 128 cores
        const val MAX_MEMORY_PER_TENANT = 524288     // 512 GiB
        const val MAX_STORAGE_PER_TENANT = 10485760  // 10 TiB
        const val MAX_BANDWIDTH_PER_TENANT = 100000  // 100 Gbps
    }

    fun initializeTenant(principal: Principal, tenantId: String, quota: QuotaAllocation): Result<String> {
        if (principal.role.level < Role.ADMIN.level) {
            return Result.failure(SecurityException("Insufficient privileges: requires ADMIN"))
        }
        if (!validateQuotaBounds(quota)) {
            return Result.failure(IllegalArgumentException("Quota exceeds maximum bounds"))
        }
        tenantQuotas[tenantId] = quota
        tenantUsage[tenantId] = QuotaAllocation(0, 0, 0, 0)
        logAudit(principal, "INIT_TENANT", tenantId)
        return Result.success("Tenant $tenantId initialized")
    }

    /**
     * Scale resources for a tenant. Computes the delta between current and requested,
     * validates the new total doesn't exceed quota, then applies.
     */
    fun scaleResources(
        principal: Principal,
        tenantId: String,
        additionalCpu: Int,
        additionalMemory: Int,
        additionalStorage: Int,
        additionalBandwidth: Int
    ): Result<QuotaAllocation> {
        if (principal.role.level < Role.DEVELOPER.level) {
            return Result.failure(SecurityException("Insufficient privileges: requires DEVELOPER"))
        }
        if (principal.tenantId != tenantId && principal.role.level < Role.SUPER_ADMIN.level) {
            return Result.failure(SecurityException("Cross-tenant access denied"))
        }

        val currentUsage = tenantUsage[tenantId]
            ?: return Result.failure(IllegalStateException("Tenant not initialized"))
        val quota = tenantQuotas[tenantId]
            ?: return Result.failure(IllegalStateException("Tenant quota not found"))

        // Calculate new totals using overflow-safe arithmetic
        val newCpu: Int
        val newMemory: Int
        val newStorage: Int
        val newBandwidth: Int
        try {
            newCpu = computeProjectedUsage(currentUsage.cpuMillicores, additionalCpu)
            newMemory = computeProjectedUsage(currentUsage.memoryMiB, additionalMemory)
            newStorage = computeProjectedUsage(currentUsage.storageGiB, additionalStorage)
            newBandwidth = computeProjectedUsage(currentUsage.networkBandwidthMbps, additionalBandwidth)
        } catch (e: IllegalArgumentException) {
            return Result.failure(IllegalArgumentException("Scaling produced out-of-range usage", e))
        }

        // Validate against quota - check that new usage doesn't exceed allocated quota
        if (!validateWithinQuota(newCpu, newMemory, newStorage, newBandwidth, quota)) {
            return Result.failure(IllegalArgumentException("Scaling would exceed tenant quota"))
        }

        val newUsage = QuotaAllocation(newCpu, newMemory, newStorage, newBandwidth)
        tenantUsage[tenantId] = newUsage
        logAudit(principal, "SCALE", tenantId)
        return Result.success(newUsage)
    }

    /**
     * Batch scale operation - applies multiple resource increments atomically.
     * Used by orchestration layer for multi-service deployments.
     */
    fun batchScale(
        principal: Principal,
        tenantId: String,
        increments: List<QuotaAllocation>
    ): Result<QuotaAllocation> {
        if (principal.role.level < Role.ADMIN.level) {
            return Result.failure(SecurityException("Batch operations require ADMIN"))
        }
        if (principal.tenantId != tenantId && principal.role.level < Role.SUPER_ADMIN.level) {
            return Result.failure(SecurityException("Cross-tenant batch access denied"))
        }

        val currentUsage = tenantUsage[tenantId]
            ?: return Result.failure(IllegalStateException("Tenant not initialized"))
        val quota = tenantQuotas[tenantId]
            ?: return Result.failure(IllegalStateException("Tenant quota not found"))

        // Aggregate all increments
        var totalCpuDelta = 0
        var totalMemoryDelta = 0
        var totalStorageDelta = 0
        var totalBandwidthDelta = 0

        for (increment in increments) {
            totalCpuDelta += increment.cpuMillicores
            totalMemoryDelta += increment.memoryMiB
            totalStorageDelta += increment.storageGiB
            totalBandwidthDelta += increment.networkBandwidthMbps
        }

        // Compute projected usage with overflow-safe arithmetic
        val projectedCpu = computeProjectedUsage(currentUsage.cpuMillicores, totalCpuDelta)
        val projectedMemory = computeProjectedUsage(currentUsage.memoryMiB, totalMemoryDelta)
        val projectedStorage = computeProjectedUsage(currentUsage.storageGiB, totalStorageDelta)
        val projectedBandwidth = computeProjectedUsage(currentUsage.networkBandwidthMbps, totalBandwidthDelta)

        if (!validateWithinQuota(projectedCpu, projectedMemory, projectedStorage, projectedBandwidth, quota)) {
            return Result.failure(IllegalArgumentException("Batch scaling would exceed quota"))
        }

        val newUsage = QuotaAllocation(projectedCpu, projectedMemory, projectedStorage, projectedBandwidth)
        tenantUsage[tenantId] = newUsage
        logAudit(principal, "BATCH_SCALE", tenantId)
        return Result.success(newUsage)
    }

    /**
     * Computes projected resource usage after applying a delta.
     * Uses widening to Long for overflow-safe arithmetic, then validates range.
     */
    private fun computeProjectedUsage(current: Int, delta: Int): Int {
        val result = current.toLong() + delta.toLong()
        // Validate result fits in non-negative Int range
        require(result in 0..Int.MAX_VALUE.toLong()) {
            "Projected usage out of valid range: $result"
        }
        return result.toInt()
    }

    private fun validateQuotaBounds(quota: QuotaAllocation): Boolean {
        return quota.cpuMillicores in 0..MAX_CPU_PER_TENANT &&
                quota.memoryMiB in 0..MAX_MEMORY_PER_TENANT &&
                quota.storageGiB in 0..MAX_STORAGE_PER_TENANT &&
                quota.networkBandwidthMbps in 0..MAX_BANDWIDTH_PER_TENANT
    }

    private fun validateWithinQuota(
        cpu: Int, memory: Int, storage: Int, bandwidth: Int,
        quota: QuotaAllocation
    ): Boolean {
        return cpu >= 0 && cpu <= quota.cpuMillicores &&
                memory >= 0 && memory <= quota.memoryMiB &&
                storage >= 0 && storage <= quota.storageGiB &&
                bandwidth >= 0 && bandwidth <= quota.networkBandwidthMbps
    }

    private fun logAudit(principal: Principal, action: String, target: String) {
        val entry = "${System.currentTimeMillis()}|${principal.userId}|${principal.role}|$action|$target"
        val hash = MessageDigest.getInstance("SHA-256")
            .digest(entry.toByteArray())
            .joinToString("") { "%02x".format(it) }
        auditLog.add("$entry|$hash")
    }

    fun getUsage(principal: Principal, tenantId: String): Result<QuotaAllocation> {
        if (principal.tenantId != tenantId && principal.role.level < Role.ADMIN.level) {
            return Result.failure(SecurityException("Access denied"))
        }
        val usage = tenantUsage[tenantId]
            ?: return Result.failure(IllegalStateException("Tenant not found"))
        return Result.success(usage)
    }
}
